import bpy, math

def gm(n): return bpy.data.materials[n]
def link_mat(obj, material):
    if obj.data and hasattr(obj.data,'materials'): obj.data.materials.append(material)
def box_dim(name, loc, dims, material, rot=(0,0,0)):
    bpy.ops.mesh.primitive_cube_add(location=loc, rotation=rot)
    o=bpy.context.active_object; o.name=name; o.dimensions=dims; link_mat(o, material)
    mod=o.modifiers.new('bev','BEVEL'); mod.width=0.015; mod.segments=2
    return o
def cyl(name, loc, radius, depth, material, rot=(0,0,0), verts=24):
    bpy.ops.mesh.primitive_cylinder_add(vertices=verts, radius=radius, depth=depth, location=loc, rotation=rot)
    o=bpy.context.active_object; o.name=name; link_mat(o, material); return o

# 1) Remove old noren (too long, hides face)
for n in ['Noren0','Noren1','Noren2','NorenCrest0','NorenCrest1','NorenCrest2','NorenDot0','NorenDot1','NorenDot2']:
    o=bpy.data.objects.get(n)
    if o: bpy.data.objects.remove(o, do_unlink=True)

# New noren: short flaps only at top, sides fuller, center flap split/shortest so face shows
indigo=gm('NorenIndigo'); white=gm('White'); red=gm('AwningRed')
# left and right flaps longer, center two short with gap in middle
box_dim('NorenL',(-2.45,-0.30,3.12),(1.7,0.06,0.80), indigo)
box_dim('NorenR',(2.45,-0.30,3.12),(1.7,0.06,0.80), indigo)
box_dim('NorenCL',(-0.85,-0.30,3.28),(1.35,0.06,0.48), indigo)
box_dim('NorenCR',(0.85,-0.30,3.28),(1.35,0.06,0.48), indigo)
for i,x in enumerate([-2.45,2.45]):
    cyl(f'NorenCrestNew{i}',(x,-0.35,3.18),0.22,0.02,white,rot=(math.radians(90),0,0))
    cyl(f'NorenDotNew{i}',(x,-0.37,3.18),0.10,0.02,red,rot=(math.radians(90),0,0))

# 2) Flip bowl cones (wide side up): rotate PI around X at their center
flipped=[]
for o in list(bpy.data.objects):
    if o.name.endswith('Bowl') and 'Spoon' not in o.name and 'Cat' not in o.name and 'Stack' not in o.name:
        o.rotation_euler = (math.radians(180),0,0)
        flipped.append(o.name)

# 3) Shrink belly so it doesn't swallow the body, push slightly forward/down
b=bpy.data.objects.get('OctoBelly')
if b: b.scale=(0.50,0.38,0.52); b.location=(0.35,0.42,1.88)

# 4) Menu board: turn paper side toward front-left camera (rotate z + flip)
for n in ['MenuBoard','MenuPaper']:
    o=bpy.data.objects.get(n)
    if o: o.rotation_euler=(0,0,math.radians(162))
# move menu lines to front face (x slightly less? paper now facing -X/-Y; shift lines x -0.06)
for i in range(4):
    o=bpy.data.objects.get(f'MenuLine{i}')
    if o:
        o.rotation_euler=(0,0,math.radians(162))
        o.location.x = 3.76

# 5) Pull cameras back a bit for full framing
hero=bpy.data.objects['CamHero']; hero.location=(5.4,-9.6,3.8); hero.rotation_euler=(math.radians(76),0,math.radians(30)); hero.data.lens=36
front=bpy.data.objects['CamFront']; front.location=(0.2,-10.2,2.8); front.rotation_euler=(math.radians(82),0,math.radians(1))
close=bpy.data.objects['CamClose']; close.location=(3.0,-5.2,3.1)

result={"flipped":flipped}

